\label{eigen vectors}
If ${\mathbf X}={\mathbf X}_f, {\mathbf Y}={\mathbf X}_g$ with unit vectors $\|f\|=\|g\|=1$ and $H_n$ is the $n^{\mbox{\small th}}$ $q$-Hermite polynomial, see (\ref{q-H}), then
\begin{equation}\label{E(H|X)}
{\mathbb E}(H_n({\mathbf Y})|{\mathbf X})=\langle f, g \rangle^n H_n({\mathbf X}).
\end{equation}

\label{q-regression}
\begin{equation}\label{LR}
{\mathbb E}({\mathbf X}_0|{\mathbf X}_1,\dots,{\mathbf X}_k)=\sum_{j=1}^k a_j {\mathbf X}_j
\end{equation}
and
\begin{equation}\label{QV}
{\mathbb E}({\mathbf X}_0^2|{\mathbf X}_1,\dots,{\mathbf X}_k)=(\sum_{j=1}^k a_j {\mathbf X}_j)^2+c{\mathbf I}.
\end{equation}
If $f_1\dots,f_k\in{\mathcal H}$ are linearly independent then the
  coefficients $a_j, c$ are uniquely determined by the covariance matrix
$C=[c_{i,j}]:=[\langle f_i,f_j\rangle]$.

\label{q-reg3}
If ${\mathbf X}:={\mathbf X}_f, {\mathbf Y}:={\mathbf X}_g,{\mathbf Z}:={\mathbf X}_h$ and $f,h\in{\mathcal H}$ are linearly independent unit vectors, then
\begin{equation}\label{LR3}
{\mathbb E}({\mathbf Y}|{\mathbf X},{\mathbf Z})=a{\mathbf X}+b{\mathbf Z},
\end{equation}
\begin{equation}\label{QV3}
{\mathbb E}({\mathbf Y}^2|{\mathbf X},{\mathbf Z})=\left(a{\mathbf X}+b{\mathbf Z}\right)^2+c{\mathbf I},
\end{equation}
where
\begin{eqnarray}
\label{a} a&=& \frac{\langle f, g \rangle - \langle g , h\rangle \langle f, h \rangle}{
 1-\langle f, h \rangle^2}, \\
\label{b} b&=&\frac{\langle g, h \rangle - \langle f , g\rangle \langle f, h\rangle}{
 1-\langle f, h \rangle^2}.
                                                                      
\end{eqnarray}

\label{q-reg classic}
If $(\tilde{X},\tilde{Y},\tilde{Z})$ is a classical version of the $q$-Gaussian triplet (\ref{triplet}) then
\begin{equation}
\label{LR-c}
E(\tilde{Y}|\tilde{X},\tilde{Z})=a\tilde{X}+b\tilde{Z},\end{equation}
\begin{equation}\label{QV-c}
E(\tilde{Y}^2|\tilde{X},\tilde{Z})=A\tilde{X}^2+B\tilde{X}\tilde{Z}+C\tilde{Z}^2+D,
\end{equation}
where
 $a,b$ are given by (\ref{a}),(\ref{b}),
\begin{eqnarray}
\label{A} A&=&\frac{ab(1-q)\langle f, h \rangle+a^2(1-q\langle f, h \rangle^2)}{1-q\langle f, h \rangle^2},
\\
\label{B} B&=&\frac{ab(1+q)(1-\langle f, h \rangle^2)}{1-q\langle f, h \rangle^2},
\\
\label{C} C&=&\frac{ab(1-q)\langle f, h \rangle+b^2(1-q\langle f, h \rangle^2)}{1-q\langle f, h \rangle^2},
\end{eqnarray}
 and
\begin{equation}\label{D}
D=1-A-B\langle f, h \rangle -C.
\end{equation}

\label{switch}
If $H_n,H_m$ are $q$-Hermite polynomials given by (\ref{q-H}),
                          
then

\begin{eqnarray}
\label{H(X)ZXH(Z)} \\ \nonumber
{\mathbb E}\left(H_n({\mathbf X}){\mathbf Z}{\mathbf X} H_m({\mathbf Z})\right)&=&
\left\{\begin{array}{ll}
\langle f, h \rangle^{n+1}[n+2]_q! & \mbox{ if } m=n+2 \\
\langle f, h \rangle^{n-1}[n]_q! & \mbox{ if } m=n-2 \\
\langle f, h \rangle^{n-1}\left(([n]_q+1)\langle f, h \rangle^2+q[n]_q\right)[n]_q! & \mbox{ if } m=n \\
0 & \mbox{ otherwise }
\end{array}\right.,
\\
\label{H(X)XZH(Z)} \\ \nonumber
{\mathbb E}\left(H_n({\mathbf X}){\mathbf X}{\mathbf Z} H_{m}({\mathbf Z})\right)&=&
\left\{\begin{array}{ll}
\langle f, h \rangle^{n+1}[n+2]_q! & \mbox{ if } m=n+2 \\
\langle f, h \rangle^{n-1}[n]_q! & \mbox{ if } m=n-2 \\
\langle f, h \rangle^{n-1}\left([n+1]_q\langle f, h \rangle^2+[n]_q\right)[n]_q! & \mbox{ if } m=n \\
0 & \mbox{ otherwise }
\end{array}\right. ,
\\\label{H(X)Z2H(Z)}\label{H(X)X2H(Z)}
{\mathbb E}\left(H_n({\mathbf X}){\mathbf X}^2H_m({\mathbf Z})\right)&=&
{\mathbb E}\left(H_m({\mathbf X}){\mathbf Z}^2H_n({\mathbf Z})\right)= \\ \nonumber &&
\left\{\begin{array}{ll}
\langle f, h \rangle^{n+2}[n+2]_q! & \mbox{ if } m=n+2 \\
\langle f, h \rangle^{n-2}[n]_q! & \mbox{ if } m=n-2 \\
{\langle f, h \rangle^n\left([n+1]_q+[n]_q\right)[n]_q!} & \mbox{ if } m=n \\
0 & \mbox{ otherwise }
\end{array}\right. ,
   
\end{eqnarray}
\begin{eqnarray}\label{L2}{\mathbb E}\left(H_n({\mathbf X}) H_m({\mathbf Z})\right)&=&
\left\{\begin{array}{ll}
\langle f, h \rangle^n[n]_q! & \mbox{ if } m=n \\
0 & \mbox{ otherwise }
\end{array}\right. .
\end{eqnarray}

\label{WWW}
Let $\tilde{X}_t$ be the classical version of the $q$-Brownian motion, i.~e.,
$\langle f_t,f_s\rangle =\min\{s,t\}$.
Then   for   $t_1<t_2<\dots<t_{n}<s<t$ we have
$$Var(\tilde{X}_{s}|\tilde{X}_{t_1},\dots,\tilde{X}_{t_n},X_t)=$$
$${\frac {\left ({ t}-{ s}
\right )\left ({ s}-{ t_n}\right )}{\left ({ t}-q{ t_n}
\right )}}\left(1+{\frac { \left ({ \tilde{X}_{t}}-{ \tilde{X}_{t_n}
}\right )\left
({ t_n} { \tilde{X}_{t}-{ t} { \tilde{X}_{t_n}}}
\right )\left (1-q\right )}{\left ({
 t}-{ t_n}\right )^{2}}}\right).
$$

\label{q-Bell}
Suppose that $(\tilde{X},\tilde{Y},\tilde{Z})$ is a classical version of $q$-Gaussian
$({\mathbf X},{\mathbf Y},{\mathbf Z}):=({\mathbf X}_f,{\mathbf X}_g,{\mathbf X}_h)$, where $f,h\in{\mathcal H}$ are linearly independent,
and $-1\leq q<1$.
If either \begin{equation}\label{sub-M}
\langle f, g\rangle \langle g, h \rangle \leq \langle f, h\rangle \mbox{ and }  0<\langle f, h \rangle<1,
\end{equation}
or $\langle f, h\rangle=0$, or $q=-1$, then inequality
(\ref{Bell}) holds true.

\label{E2}
Suppose $\langle f, h \rangle=\langle g, h \rangle=1/2$. Inequality (\ref{Bell}) used in Example \ref{E1}
implies that if a classical version of a $q$-Gaussian process exists
then $\langle f, g \rangle \geq 0$. Evaluating the conditional variance $Var(\tilde{Y}|\tilde{X},\tilde{Z})$
at $\tilde{X}=2/\sqrt{1-q},\tilde{Z}=-\tilde{X}$ we get a more restrictive constraint
$\langle f, g \rangle\geq \frac{q+5}{36}$.
